// Self-contained deployment payload for Masar Telegram Bot.
const encoded = "";
const bytes = Uint8Array.from(atob(encoded), c => c.charCodeAt(0));
const source = await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream("gzip"))).text();
function base64Utf8(text) { const bytes = new TextEncoder().encode(text); let binary = ""; for (let i = 0; i < bytes.length; i += 0x8000) binary += String.fromCharCode(...bytes.subarray(i, i + 0x8000)); return btoa(binary); }
await import("data:text/javascript;base64," + base64Utf8(source));
